exercise.solution:
def load_docs(raw):
    import json
    records = json.loads(raw)
    if not isinstance(records,list):
        raise ValueError("Expected list")
    result = []
    for record in records:
        if not isinstance(record,dict) or not all(isinstance(record.get(k),str) for k in ("id","text","source")):
            raise ValueError("Invalid document")
        result.append({k:record[k] for k in ("id","text","source")})
    return result

