exercise.solution:
def retrieve(query,docs,tenant,k):
    if k <= 0:
        return []
    terms = set(query.lower().split())
    scored = []
    for doc in docs:
        if doc.get("tenant") == tenant:
            score = len(terms & set(doc["text"].lower().split()))
            if score:
                scored.append((score,doc["id"]))
    return [i for s,i in sorted(scored,key=lambda pair:pair[0],reverse=True)[:k]]

