exercise.solution:
def rrf(rankings,c=60):
    if c <= 0:
        raise ValueError("c must be positive")
    scores = {}
    for ranking in rankings:
        for rank,doc_id in enumerate(ranking,1):
            scores[doc_id] = scores.get(doc_id,0.0)+1/(c+rank)
    return scores

