exercise.solution:
def rerank(query,candidates):
    q = query.lower()
    terms = set(q.split())
    def score(doc):
        text = doc["text"].lower()
        return len(terms & set(text.split()))+(2 if q and q in text else 0)
    return [doc["id"] for doc in sorted(candidates,key=score,reverse=True)]

