def expand_query(query,aliases):
    base = " ".join(query.split())
    extras, seen = [], set()
    for token in base.lower().split():
        if token not in seen and aliases.get(token):
            extras.append(aliases[token])
        seen.add(token)
    return " ".join([base]+extras).strip()

