def select_context(hits,budget):
    blocks, used = [], 0
    for hit in hits:
        block = f'[{hit["id"]}] {hit["text"]}'
        cost = len(block)+bool(blocks)
        if used+cost <= budget:
            blocks.append(block)
            used += cost
    return "\n".join(blocks)

