    # Implement the behavior described in the exercise.
    pass

exercise.solution:
def evidence_response(hits,budget):
    seen, texts, ids, used = set(), [], [], 0
    for hit in hits:
        if hit["id"] in seen:
            continue
        seen.add(hit["id"])
        cost = len(hit["text"])+bool(texts)
        if used+cost <= budget:
            texts.append(hit["text"])
            ids.append(hit["id"])
            used += cost
    return {"answer":"\n".join(texts) if texts else "Not enough evidence.","citations":ids,"mode":"simulated"}

