exercise.solution:
def evaluate_cases(cases):
    if not cases:
        return {"mean_recall":0.0,"citation_valid_rate":0.0}
    recalls, valid = [], 0
    for case in cases:
        found, gold = set(case["retrieved"]), set(case["relevant"])
        recalls.append(len(found & gold)/len(gold) if gold else 0.0)
        valid += set(case["citations"]).issubset(found)
    return {"mean_recall":sum(recalls)/len(cases),"citation_valid_rate":valid/len(cases)}

