exercise.solution:
def search_index(query,index,k=3):
    if k <= 0:
        return []
    terms = set(query.lower().split())
    hits = []
    for chunk in index:
        score = len(terms & set(chunk["text"].lower().split()))
        if score:
            hits.append({**chunk,"score":score})
    return sorted(hits,key=lambda h:h["score"],reverse=True)[:k]

