def answer_question(question,docs,size=40):
    # Implement the behavior described in the exercise.
    pass

exercise.solution:
def answer_question(question,docs,size=40):
    if size <= 0:
        raise ValueError("size must be positive")
    terms, hits = set(question.lower().split()), []
    for doc in docs:
        words = doc["text"].split()
        for i,start in enumerate(range(0,len(words),size)):
            text = " ".join(words[start:start+size])
            score = len(terms & set(text.lower().split()))
            if score:
                hits.append({"id":f'{doc["id"]}:{i}',"text":text,"source":doc["source"],"score":score})
    hits.sort(key=lambda h:h["score"],reverse=True)
    if not hits:
        return {"mode":"simulated","answer":"Not enough evidence.","citations":[],"sources":[]}
    hit = hits[0]
    return {"mode":"simulated","answer":hit["text"],"citations":[hit["id"]],"sources":[hit["source"]]}
